SELECT COALESCE(
    SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics_json, '$.dailySpend')) AS DECIMAL(18, 2))),
    0
)
FROM biz_delivery_report
WHERE reporter_id = #{userId}
  AND project_id = #{projectId}
  AND report_date BETWEEN #{startDate} AND #{endDate}
  AND deleted_at = 0
  AND agency_line_name IN

    #{line}

  AND LOWER(TRIM(platform)) IN

    #{platform}
